 12	public abstract class CSVReader
 13	{
 14	    private static final String CSV_SEPARATOR = ",";
 15	    protected final ErrorThrower errorThrower;
 16	
 17	    /**
 18	     * Empty constructor for this class.
 19	     */
 20	    public CSVReader()
 21	    {
