 27	     * orchestrating the process of reading data from the .csv file and populating
 28	     * the appropriate fields with the read data.
 29	     *
 30	     * @param nameOfElementToLookFor (String) the name of the element which data must be extracted
 31	     */
 32	    public void extractDataFor(String nameOfElementToLookFor)
 33	    {
 34	        resetParameters();
 35	        String[] extractedData = findRowByName(nameOfElementToLookFor);
 36	        if (extractedData != null) {
 37	            populateFields(extractedData);
 38	        } else {
 39	            System.out.println("ERROR: no data could be read for " + nameOfElementToLookFor);
 40	        }
 41	    }
