 45	     * (the path to this file depends on the children class from which this method is called)
 46	     * Source: technique to read .csv files was found on https://stackabuse.com/reading-and-writing-csvs-in-java/
 47	     *
 48	     * @param nameOfElementToLookFor (String) the name of the element which data must be extracted
 49	     * @return (String[]) the extracted data
 50	     */
 51	    private String[] findRowByName(String nameOfElementToLookFor)
 52	    {
 53	        for (String[] row : readDataRows()) {
 54	            if (row[0].equals(nameOfElementToLookFor)) {
 55	                return row;
 56	            }
 57	        }
 58	        return null;
 59	    }
 60	
 61	    /**
 62	     * Abstract method that must be overridden with the appropriate behaviours
 63	     * needed to populate the fields of the child class.
 64	     *
 65	     * @param extractedData (String[]) The data extracted from the .csv file.
 66	     */
 67	    abstract void populateFields(String[] extractedData);
 68	
